wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert a day count relative to the Unix epoch (1970-01-01 = 0) into a
/// proleptic-Gregorian (year, month, day), via Howard Hinnant's algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The one authority this node holds: read the wall clock.
        let now = wall_clock::now();

        // `started`: the instant the run began. u64 is non-negative by type,
        // so `started >= 0` holds by construction.
        let started = now.seconds;

        // `date`: the UTC calendar date the run publishes under.
        let days = (started / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        // Clamp the year into [0, 9999] so the formatted string is always
        // exactly 10 characters ("YYYY-MM-DD"), satisfying len(date) == 10.
        let y = y.clamp(0, 9999);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo { date, started }
    }
}

export!(Node);
```

